SELECT LAG(SUM(x0.v52915 / x0.v52913), 1, 1 + SUM(x0.v52913 / x0.v52917)) OVER (ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), RANK() OVER (ORDER BY CASE WHEN x0.v52914 IS NULL THEN 1 ELSE 0 END DESC, x0.v52914 DESC) FROM v52912 AS x0 WINDOW x1 AS (ORDER BY x0.v52913 ROWS BETWEEN INTERVAL '2' DAY PRECEDING AND UNBOUNDED FOLLOWING)